```cpp
#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> nums = {5, 2, 8, 1, 3};

    // لیبڈا نزولی ترتیب میں ترتیب دینے کے لیے
    std::sort(nums.begin(), nums.end(), [](int a, int b) {
        return a > b;
    });

    // لیبڈا ہر عنصر کو پرنٹ کرنے کے لیے
    std::for_each(nums.begin(), nums.end(), [](int n) {
        std::cout << n << " ";
    });

    return 0;
}
```
آؤٹ پٹ: `8 5 3 2 1`
